{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section heading designating 29 CFR 825.110 regarding eligible employees, containing no independent operative requirements or rights."
    },
    {
      "quote_ref": "F001:F002",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "An eligible employee is an employee of a covered employer who has been employed by the employer for at least 12 months."
    },
    {
      "quote_ref": "F001:F003",
      "scope_refs": [],
      "kind": "threshold",
      "meaning": "To be an eligible employee, the employee must have been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of the leave (subject to special rules in § 825.801 for airline flight crew employees)."
    },
    {
      "quote_ref": "F001:F004",
      "scope_refs": [],
      "kind": "threshold",
      "meaning": "To be an eligible employee, the employee must be employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite (referencing § 825.105(b) regarding employees who work outside the U.S.)."
    },
    {
      "quote_ref": "F005",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The 12 months an employee must have been employed by the employer need not be consecutive months, subject to the conditions in paragraph (b)."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F005"],
      "kind": "exemption",
      "meaning": "Subject to the exceptions in paragraph (b)(2), employment periods prior to a break in service of seven years or more need not be counted when determining whether the employee has been employed by the employer for at least 12 months."
    },
    {
      "quote_ref": "F007:F008",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted in determining whether an employee has been employed for at least 12 months where the employee's break in service is occasioned by fulfilling a USERRA-covered service obligation, and the period of absence due to or necessitated by USERRA-covered service must also be counted, provided this section gives no greater entitlement than available under USERRA."
    },
    {
      "quote_ref": "F007:F009",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted in determining whether an employee has been employed for at least 12 months where a written agreement, including a collective bargaining agreement, exists concerning the employer's intention to rehire the employee after the break in service (such as for education or childrearing purposes)."
    },
    {
      "quote_ref": "F010",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "If an employee is maintained on the payroll for any part of a week, including periods of paid or unpaid leave (sick, vacation) during which other benefits or compensation are provided by the employer (such as workers' compensation or group health plan benefits), that week counts as a week of employment."
    },
    {
      "quote_ref": "F010",
      "scope_refs": [],
      "kind": "threshold",
      "meaning": "For the purpose of determining whether intermittent, occasional, or casual employment qualifies as at least 12 months, 52 weeks is deemed equal to 12 months."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "Employers are not prevented from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "If an employer chooses to recognize prior employment before a continuous break in service of more than seven years, the employer must do so uniformly with respect to all employees with similar breaks in service."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "Except as provided in paragraph (c)(2) and § 825.801 for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined by the number of hours worked for the employer within the meaning of compensable hours of work under FLSA principles (29 CFR part 785)."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The determination of hours worked is not limited by methods of recordkeeping or inaccurate compensation agreements; any accurate accounting of actual hours worked under FLSA principles may be used."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employee returning from USERRA-covered service must be credited with the hours of service that would have been performed but for the absence necessitated by USERRA-covered service when determining FMLA eligibility, adding those hours to hours actually worked during the previous 12-month period."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "To determine the hours that would have been worked during an absence due to USERRA-covered service, the employee's pre-service work schedule can generally be used for calculations (referencing § 825.801(c) for airline flight crew employees)."
    },
    {
      "quote_ref": "F014",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "If an employer does not maintain an accurate record of hours worked by an employee, including employees exempt from FLSA recordkeeping requirements (such as executive, administrative, and professional employees under 29 CFR part 541), the employer bears the burden of showing that the employee has not worked the requisite hours."
    },
    {
      "quote_ref": "F014",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Where an employer claims that full-time teachers of an elementary or secondary school system, institution of higher education, or other educational establishment are not eligible for FMLA leave, the employer must be able to clearly demonstrate that the teachers did not work 1,250 hours during the previous 12 months (referencing § 825.801(d) for airline flight crew employees)."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The determination of whether an employee meets the hours of service requirement and has been employed for a total of at least 12 months must be made as of the date the FMLA leave is to start."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "An employee may be on non-FMLA leave when meeting the 12-month eligibility requirement; in that event, any portion of the leave taken for an FMLA-qualifying reason after meeting the requirement is FMLA leave (referencing § 825.300(b) for eligibility notice rules)."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Whether 50 employees are employed within 75 miles to determine FMLA eligibility is determined when the employee gives notice of the need for leave."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "Once an employee is determined eligible in response to a notice of the need for leave (whether taken all at once, intermittently, or on a reduced schedule), that eligibility for that specific notice is not affected by any subsequent change in the employee count within 75 miles of the worksite."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "An employer may not terminate an employee's leave that has already started if the employee count drops below 50."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "If an employer employs 60 employees in August but expects the count to drop to 40 in December, the employer must grant FMLA benefits to an otherwise eligible employee who gives notice in August for leave beginning in December."
    }
  ]
}
